const { owner, repo } = context.repo;

function parseManifestArtifact(artifact) {
  const match = artifact.name.match(/^beta-release-manifest-(\d+)-(\d+)$/);
  if (!match) {
    return null;
  }

  return {
    artifact,
    runId: match[1],
    runAttempt: match[2]
  };
}

let selectedRunId = null;
let selectedRunAttempt = null;
let selectedRunUrl = null;
let manifestArtifactName = null;

if (overrideRunId) {
  const { data } = await github.rest.actions.getWorkflowRun({
    owner,
    repo,
    run_id: Number(overrideRunId)
  });

  const expectedArtifactName = `beta-release-manifest-${data.id}-${data.run_attempt}`;
  const { data: artifactsData } = await github.rest.actions.listWorkflowRunArtifacts({
    owner,
    repo,
    run_id: Number(overrideRunId),
    name: expectedArtifactName,
    per_page: 100
  });
  const manifestArtifact = artifactsData.artifacts.find((artifact) => artifact.name === expectedArtifactName);

  if (!manifestArtifact) {
    core.setFailed(
      `Workflow run ${data.id} (attempt ${data.run_attempt}) does not have the expected beta release manifest artifact.`
    );
    return;
  }

  selectedRunId = String(data.id);
  selectedRunAttempt = String(data.run_attempt);
  selectedRunUrl = data.html_url;
  manifestArtifactName = manifestArtifact.name;
} else {
  const { data } = await github.rest.actions.listArtifactsForRepo({
    owner,
    repo,
    per_page: 100
  });

  const matchingArtifacts = data.artifacts
    .filter((artifact) => !artifact.expired)
    .map(parseManifestArtifact)
    .filter((candidate) => candidate !== null)
    .filter((candidate) => candidate.artifact.workflow_run?.head_branch === 'main')
    .sort((left, right) => {
      const leftCreatedAt = left.artifact.created_at ?? "";
      const rightCreatedAt = right.artifact.created_at ?? "";
      return rightCreatedAt.localeCompare(leftCreatedAt);
    });

  const latestArtifact = matchingArtifacts[0];
  if (!latestArtifact) {
    core.setFailed('Unable to resolve a beta release manifest artifact from the main branch.');
    return;
  }

  selectedRunId = latestArtifact.runId;
  selectedRunAttempt = latestArtifact.runAttempt;
  selectedRunUrl = `${context.serverUrl}/${owner}/${repo}/actions/runs/${latestArtifact.runId}`;
  manifestArtifactName = latestArtifact.artifact.name;
}

core.setOutput('run_id', selectedRunId);
core.setOutput('run_attempt', selectedRunAttempt);
core.setOutput('run_url', selectedRunUrl);
core.setOutput('manifest_artifact_name', manifestArtifactName);
